@lru_cache(maxsize=1)
def original_answers():
    path = Path(__file__).resolve().parents[2] / "data" / "faq.json.bak"
    return {row["id"]: row["answer"] for row in json.loads(path.read_text(encoding="utf-8"))}


def translation(key, answer, language):
    if key in TEXT and original_answers().get(key) == answer:
        return TEXT[key][0 if language == "ru" else 1]
